/// @brief Point in 2D space.
///
/// @since_tizen 2.4
final class mv_point_s extends ffi.Struct {
  /// < X-axis coordinate of the point in 2D space
  @ffi.Int()
  external int x;

  /// < Y-axis coordinate of the point in 2D space
  @ffi.Int()
  external int y;
}

/// @brief Location of the object bounded by quadrangle defined by four 2D points.
///
/// @since_tizen 2.4
final class mv_quadrangle_s extends ffi.Struct {
  /// < Four points that define object bounding
  /// quadrangle
  @ffi.Array.multi([4])
  external ffi.Array<mv_point_s> points;
}

/// @brief Location of the object bounded by rectangle defined by
/// coordinates of top left corner, width and height.
///
/// @since_tizen 2.4
final class mv_rectangle_s extends ffi.Struct {
  /// < Top left corner of rectangle coordinates
  external mv_point_s point;

  /// < Width of the bounding rectangle
  @ffi.Int()
  external int width;

  /// < Height of the bounding rectangle
  @ffi.Int()
  external int height;
}

/// @brief Enumeration for Media Vision error.
///
/// @since_tizen 2.4
abstract class mv_error_e {
  /// < Successful
  static const int MEDIA_VISION_ERROR_NONE = 0;

  /// < Not supported
  static const int MEDIA_VISION_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Message too long
  static const int MEDIA_VISION_ERROR_MSG_TOO_LONG = -90;

  /// < No data
  static const int MEDIA_VISION_ERROR_NO_DATA = -61;

  /// < Key not available
  static const int MEDIA_VISION_ERROR_KEY_NOT_AVAILABLE = -126;

  /// < Out of memory
  static const int MEDIA_VISION_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int MEDIA_VISION_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid operation
  static const int MEDIA_VISION_ERROR_INVALID_OPERATION = -38;

  /// < Not permitted
  static const int MEDIA_VISION_ERROR_PERMISSION_DENIED = -1;

  /// < Not supported format
  static const int MEDIA_VISION_ERROR_NOT_SUPPORTED_FORMAT = -27066367;

  /// < Internal error
  static const int MEDIA_VISION_ERROR_INTERNAL = -27066366;

  /// < Invalid data
  static const int MEDIA_VISION_ERROR_INVALID_DATA = -27066365;

  /// < Invalid path (Since 3.0)
  static const int MEDIA_VISION_ERROR_INVALID_PATH = -27066364;

  /// < Not supported engine (Since 5.5.)
  static const int MEDIA_VISION_ERROR_NOT_SUPPORTED_ENGINE = -27066363;
}

