  /// < The colorspace type is Y800
  static const int MEDIA_VISION_COLORSPACE_Y800 = 1;

  /// < The colorspace type is I420
  static const int MEDIA_VISION_COLORSPACE_I420 = 2;

  /// < The colorspace type is NV12
  static const int MEDIA_VISION_COLORSPACE_NV12 = 3;

  /// < The colorspace type is YV12
  static const int MEDIA_VISION_COLORSPACE_YV12 = 4;

  /// < The colorspace type is NV21
  static const int MEDIA_VISION_COLORSPACE_NV21 = 5;

  /// < The colorspace type is YUYV
  static const int MEDIA_VISION_COLORSPACE_YUYV = 6;

  /// < The colorspace type is UYVY
  static const int MEDIA_VISION_COLORSPACE_UYVY = 7;

  /// < The colorspace type is 422P
  static const int MEDIA_VISION_COLORSPACE_422P = 8;

  /// < The colorspace type is RGB565
  static const int MEDIA_VISION_COLORSPACE_RGB565 = 9;

  /// < The colorspace type is RGB888
  static const int MEDIA_VISION_COLORSPACE_RGB888 = 10;

  /// < The colorspace type is RGBA
  static const int MEDIA_VISION_COLORSPACE_RGBA = 11;
}

/// @brief The handle to the source.
